impl Solution {
    pub fn classify_t_primes(nums: Vec<u64>) -> Vec<bool> {
        let max_num = *nums.iter().max().unwrap_or(&0);
        let max_sqrt = (max_num as f64).sqrt() as u64 + 1;

        // Sieve of Eratosthenes to find primes up to max_sqrt
        let mut is_prime = vec![true; max_sqrt as usize];
        is_prime[0] = false;
        is_prime[1] = false;
        for i in 2..max_sqrt {
            if is_prime[i as usize] {
                let mut j = i * i;
                while j < max_sqrt {
                    is_prime[j as usize] = false;
                    j += i;
                }
            }
        }

        nums.into_iter()
            .map(|x| {
                if x < 4 {
                    return false;
                }
                let root = (x as f64).sqrt() as u64;
                if root * root != x {
                    return false;
                }
                is_prime[root as usize]
            })
            .collect()
    }
